BOSS_OPERATION = "boss"
CUT_OPERATION = "cut"
REVOLVE_BOSS_OPERATION = "revolve-boss"
REVOLVE_CUT_OPERATION = "revolve-cut"

BLIND_END = "blind"
THROUGH_ALL_END = "through-all"
MID_PLANE_END = "mid-plane"
FULL_REVOLUTION_END = "full-revolution"

FRONT_SUPPORT = "front"
TOP_SUPPORT = "top"
RIGHT_SUPPORT = "right"
FACE_SUPPORT = "face"
SKETCH_AXIS_SUPPORT = "sketch-axis"
REFERENCE_AXIS_SUPPORT = "reference-axis"

RECTANGLE_PROFILE = "rectangle"
CIRCLE_PROFILE = "circle"
RECTANGLE_WITH_CIRCLE_PROFILE = "rectangle+circle"
POLYLINE_PROFILE_PREFIX = "polyline-"

SUPPORTED_END_CONDITIONS = frozenset({BLIND_END, THROUGH_ALL_END, MID_PLANE_END})
DEPTHLESS_END_CONDITIONS = frozenset({THROUGH_ALL_END})
REVOLVE_OPERATIONS = frozenset({REVOLVE_BOSS_OPERATION, REVOLVE_CUT_OPERATION})
REVOLVE_SUPPORTS = frozenset({SKETCH_AXIS_SUPPORT, REFERENCE_AXIS_SUPPORT})
REVOLVE_END_CONDITIONS = frozenset({FULL_REVOLUTION_END})
FULL_REVOLUTION_DEGREES = 360.0
MAXIMUM_REVOLUTION_DEGREES = FULL_REVOLUTION_DEGREES
_DEGREE_TOLERANCE = 1.0e-9
_AXIS_TOLERANCE = 1.0e-9
DONOR_END_CONDITIONS = MappingProxyType(
    {
        BLIND_END: BLIND_END,
        MID_PLANE_END: BLIND_END,
        THROUGH_ALL_END: THROUGH_ALL_END,
    }
)
END_CONDITION_CODES = MappingProxyType({BLIND_END: 0, MID_PLANE_END: 6})
GENERATED_CONTAINER_FEATURE_LIMIT = 1
CONTAINER_DICTIONARY_WINDOW = 32768


@dataclass(frozen=True, slots=True)
class DonorContainerStream:
    names: tuple[str, ...]
    stream_bytes: int
    encoded: tuple[str, ...]


def _container_payload(item: DonorContainerStream, dictionary: bytes) -> bytes:
    engine = zlib.decompressobj(-15, zdict=dictionary)
    blob = engine.decompress(base64.b85decode("".join(item.encoded))) + engine.flush()
    if len(blob) != item.stream_bytes:
        raise SldprtFormatError(f"donor container stream {item.names[0]} is corrupt")
    return blob


@dataclass(frozen=True, slots=True)
class DonorFeature:
    operation: str
    profile: str
    support: str
    end_condition: str

    @property
    def key(self) -> tuple[str, str, str, str]:
        return self.operation, self.profile, self.support, self.end_condition


@dataclass(frozen=True, slots=True)
class TargetFeature:
    operation: str
    profile: str
    support: str
    end_condition: str
    points_mm: tuple[tuple[float, float], ...] = ()
    radii_mm: tuple[float, ...] = ()
    arc_centres_mm: tuple[tuple[float, float], ...] = ()
    depth_mm: float | None = None
    reversed: bool | None = None
    angle_degrees: float | None = None
    axis_direction: tuple[float, float] | None = None

    @property
    def revolve(self) -> bool:
        return self.operation in REVOLVE_OPERATIONS

    @property
    def topology(self) -> DonorFeature:
        return DonorFeature(
            self.operation, self.profile, self.support, self.end_condition
        )


@dataclass(frozen=True, slots=True)
class Donor:
    donor_id: str
    features: tuple[DonorFeature, ...]
    feature_ids: tuple[int, ...]
    sketch_ids: tuple[int, ...]
    feature_names: tuple[str, ...]
    sketch_names: tuple[str, ...]
    point_counts: tuple[int, ...]
    arc_counts: tuple[int, ...]
    depth_present: tuple[bool, ...]
    stream_bytes: int
    encoded: tuple[str, ...]
    measured: bool = False
    axis_directions: tuple[tuple[float, float] | None, ...] = ()

    @property
    def key(self) -> tuple[tuple[str, str, str, str], ...]:
        return tuple(feature.key for feature in self.features)

    @property
    def stream(self) -> bytes:
        blob = zlib.decompress(base64.b85decode("".join(self.encoded)))
        if len(blob) != self.stream_bytes:
            raise SldprtFormatError(
                f"donor {self.donor_id} resolved-features stream is corrupt"
            )
        return blob

    @property
    def container(self) -> Mapping[str, bytes]:
        result: dict[str, bytes] = {}
        for item in _DONOR_CONTAINERS.get(self.donor_id, ()):
            blob = _container_payload(item, CONTAINER_DICTIONARIES[item.names[0]])
            for name in item.names:
                result[name] = blob
        return MappingProxyType(result)


