DONOR_LIBRARY: tuple[Donor, ...] = (
    _DONOR_BOSS1_FRONT_RECT_BLIND,
    _DONOR_BOSS2_FRONT_RECT_BLIND,
    _DONOR_BOSS3_FRONT_RECT_BLIND,
    _DONOR_BOSS4_FRONT_RECT_BLIND,
    _DONOR_BOSS5_FRONT_RECT_BLIND,
    _DONOR_BOSS6_FRONT_RECT_BLIND,
    _DONOR_BOSS7_FRONT_RECT_BLIND,
    _DONOR_BOSS8_FRONT_RECT_BLIND,
    _DONOR_BOSS_CUT,
    _DONOR_BOSS_CUT_CUT,
    _DONOR_BOSS_CUT_BOSS,
    _DONOR_BOSS_CUT_CUT_CUT,
    _DONOR_BOSS_BOSS_CUT_CUT,
    _DONOR_BOSS_CUT_THROUGH,
    _DONOR_BOSS_CUT_MIDPLANE,
    _DONOR_BOSS_MIDPLANE,
    _DONOR_CIRCLE_BOSS,
    _DONOR_RECT_HOLE_BOSS,
    _DONOR_BOSS_TOP_PLANE,
    _DONOR_BOSS_RIGHT_PLANE,
    _DONOR_POLY6_BOSS,
    _DONOR_POLY12_CUT_THROUGH,
    _DONOR_BOSS_CUT_CUT_BLIND,
    _DONOR_BOSS_CUT_CUT_CUT_THROUGH,
    _DONOR_REVOLVE_FULL,
    _DONOR_BOSS_REVCUT,
)

DONORS_BY_KEY = MappingProxyType(
    {donor.key: donor for donor in reversed(DONOR_LIBRARY)}
)
DONORS_BY_ID = MappingProxyType({donor.donor_id: donor for donor in DONOR_LIBRARY})


def polyline_profile(segment_count: int) -> str:
    return f"{POLYLINE_PROFILE_PREFIX}{segment_count}"


def donor_key(
    targets: Sequence[TargetFeature],
) -> tuple[tuple[str, str, str, str], ...]:
    return tuple(
        (
            target.operation,
            target.profile,
            target.support,
            DONOR_END_CONDITIONS.get(target.end_condition, target.end_condition),
        )
        for target in targets
    )


def select_donor(targets: Sequence[TargetFeature]) -> Donor | None:
    if not targets:
        return None
    return DONORS_BY_KEY.get(donor_key(targets))


def donor_edits(
    donor: Donor, targets: Sequence[TargetFeature]
) -> dict[int, FeatureEdit]:
    if len(targets) != len(donor.features):
        raise SldprtFormatError(
            f"donor {donor.donor_id} holds {len(donor.features)} features and "
            f"{len(targets)} were supplied"
        )
    edits: dict[int, FeatureEdit] = {}
    for ordinal, target in enumerate(targets):
        if len(target.points_mm) != donor.point_counts[ordinal]:
            raise SldprtFormatError(
                f"donor {donor.donor_id} feature {ordinal} holds "
                f"{donor.point_counts[ordinal]} sketch points and "
                f"{len(target.points_mm)} were supplied"
            )
        if len(target.radii_mm) != donor.arc_counts[ordinal]:
            raise SldprtFormatError(
                f"donor {donor.donor_id} feature {ordinal} holds "
                f"{donor.arc_counts[ordinal]} sketch arcs and "
                f"{len(target.radii_mm)} were supplied"
            )
        if len(target.arc_centres_mm) != donor.arc_counts[ordinal]:
            raise SldprtFormatError(
                f"donor {donor.donor_id} feature {ordinal} holds "
                f"{donor.arc_counts[ordinal]} sketch arcs and "
                f"{len(target.arc_centres_mm)} centres were supplied"
            )
        if target.revolve:
            edits[ordinal] = _revolve_edit(donor, ordinal, target)
            continue
        depth_required = target.end_condition not in DEPTHLESS_END_CONDITIONS
        if depth_required != donor.depth_present[ordinal]:
            raise SldprtFormatError(
                f"donor {donor.donor_id} feature {ordinal} cannot hold the "
                f"{target.end_condition} end condition"
            )
        if target.end_condition not in SUPPORTED_END_CONDITIONS:
            raise SldprtFormatError(
                f"unsupported end condition {target.end_condition!r}"
            )
        if depth_required and (
            target.depth_mm is None
            or not math.isfinite(target.depth_mm)
            or target.depth_mm <= 0.0
        ):
            raise SldprtFormatError(
                f"feature {ordinal} requires a finite positive depth"
            )
        edits[ordinal] = FeatureEdit(
            corners_mm=tuple(target.points_mm) or None,
            radii_mm=tuple(target.radii_mm) or None,
            arc_centres_mm=tuple(target.arc_centres_mm) or None,
            depth_mm=target.depth_mm if depth_required else None,
            reversed=target.reversed,
            end_condition_code=END_CONDITION_CODES.get(target.end_condition),
        )
    return edits


def _parallel(left: tuple[float, float], right: tuple[float, float]) -> bool:
    return abs(left[0] * right[1] - left[1] * right[0]) <= _AXIS_TOLERANCE and (
        abs(left[0] * right[0] + left[1] * right[1]) > _AXIS_TOLERANCE
    )


def _revolve_edit(donor: Donor, ordinal: int, target: TargetFeature) -> FeatureEdit:
    if target.end_condition not in REVOLVE_END_CONDITIONS:
        raise SldprtFormatError(
            f"donor {donor.donor_id} feature {ordinal} cannot hold the "
            f"{target.end_condition} revolution end condition"
        )
    if target.support not in REVOLVE_SUPPORTS:
        raise SldprtFormatError(
            f"donor {donor.donor_id} feature {ordinal} cannot revolve about a "
            f"{target.support} axis"
        )
    if donor.depth_present[ordinal] or target.depth_mm is not None:
        raise SldprtFormatError(
            f"donor {donor.donor_id} feature {ordinal} is a revolution and carries "
            f"an angle, not a depth"
        )
    if target.reversed is not None:
        raise SldprtFormatError(
            f"donor {donor.donor_id} feature {ordinal} is a revolution whose "
            f"direction flag is not located, so a direction cannot be written"
        )
    inherited = (
        donor.axis_directions[ordinal] if ordinal < len(donor.axis_directions) else None
    )
    if inherited is None:
        raise SldprtFormatError(
            f"donor {donor.donor_id} feature {ordinal} records no revolution axis "
            f"direction to inherit"
        )
    if target.axis_direction is None or not _parallel(target.axis_direction, inherited):
        raise SldprtFormatError(
            f"donor {donor.donor_id} feature {ordinal} revolves about the "
            f"{inherited} sketch axis and cannot be repointed"
        )
    angle = target.angle_degrees
    if (
        angle is None
        or not math.isfinite(angle)
        or angle <= 0.0
        or angle > MAXIMUM_REVOLUTION_DEGREES + _DEGREE_TOLERANCE
    ):
        raise SldprtFormatError(
            f"feature {ordinal} requires a revolution angle inside (0, 360] degrees"
        )
    return FeatureEdit(
        corners_mm=tuple(target.points_mm) or None,
        radii_mm=tuple(target.radii_mm) or None,
        arc_centres_mm=tuple(target.arc_centres_mm) or None,
        angle_radians=math.radians(angle),
    )


def patch_donor(donor: Donor, targets: Sequence[TargetFeature]) -> bytes:
    stream = donor.stream
    located = locate_features(stream)
    if len(located) != len(donor.features):
        raise SldprtFormatError(
            f"donor {donor.donor_id} resolved-features stream no longer locates "
            f"{len(donor.features)} features"
        )
    return patch_features(stream, donor_edits(donor, targets))


def donor_by_id(donor_id: str) -> Donor:
    donor = DONORS_BY_ID.get(donor_id)
    if donor is None:
        raise SldprtFormatError(f"unknown SOLIDWORKS donor {donor_id!r}")
    return donor
